quests[79507] = { id = 79507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Day the Stoneheads Came", description = "What? Want scary story?\n\nYou ask. Granny Scribbles give what want. Maybe then sit still like good tenderfoots.\n\nScariest story Granny know, yes. Story about the day the stoneheads came...", progress = "Hope story not too scary for you.", completion = "<Granny Scribbles gestures around to the room.>\n\nNot all stoneheads bad, seems like.\n\nStill, little kobold need know what happen. What can happen.", objectives = "Relive Granny Scribbles' story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79508] = { id = 79508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mipsy Mole-Rider", description = "Time for happy story. Not all days bad.\n\n<Granny Scribbles gently scratches Ol' Snorler behind his ears.>\n\nTell story of how be friends with moles. Story of Mipsy mole-rider...", progress = "You listening?", completion = "Tenderfoots always fan of that one.\n\nWhat you think of mole? Think ride good as Mipsy?", objectives = "Relive Granny Scribbles' story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79510] = { id = 79510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wickless Candle", description = "Now tell story of very far place called \"surface\". New friend from there, yes, so they know what Granny Scribbles talk about.\n\n<Granny Scribbles nods sagely as she points you out.>\n\nStory of how kobold discover it long go, and what find when do. Story of the wickless candle...", progress = "Sound like place you know?", completion = "You not bad listener, {name}. Name you honorary tenderfoot, Granny Scribbles thinks.\n\nMaybe next time you tell Granny Scribbles story. Never too old to learn new one.", objectives = "Relive Granny Scribbles' story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79511] = { id = 79511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Identity Crisis", completion = "I take it Chromie sent you?", objectives = "Speak with Emberthal in the Victorious Visage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79512] = { id = 79512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Are You?", progress = "Have you completed your reconnaissance yet?", completion = "Interesting... These are quite the varied answers.", objectives = "Speak with 9 Valdrakken Visitors in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79513] = { id = 79513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Adventuring: Being Yourself", description = "I worry about Emberthal. Her mood has grown increasingly dark.\n\nBy sticking to citizens of the city, she is looking for ways she is similar to them, instead of what makes her unique.\n\nPerhaps a broader sample size is in order?\n\nShe needs stories to guide her. There are many such individuals with stories to tell in the Dragon Isles.\n\nGo, and speak with them. \n\nWould that I could go myself, but the duties of a Scalecommander never rest.", progress = "Have you spoken with everyone?", completion = "Thank you, {name}. If these do not help Emberthal, I do not think anything can.", objectives = "Speak with 8 residents of the Dragon Isles and listen to their stories.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79514] = { id = 79514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Threaten Me With a Good Time", description = "Emberthal seems worried, but I'm sure she'll come back. And when she does, she'll pick a visage form!\n\nChromie told us all about the celebrations dragons used to have for Visage Day.\n\nSo, Kalecgos and I are going to blow stuff up! Fireworks, mostly.\n\nWe'll need some arcane residue to make them, though.\n\nConveniently, there are some arcane elementals just outside the Gardens of Unity that are ripe for the harvest.\n\nThe three of us have some other preparations to make here in Valdrakken.", progress = "These volatile elementals make the perfect base for fireworks!", completion = "Now we're talking!", objectives = "Collect 100 Arcane Residue from Volatile Arcana in The Cascades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79515] = { id = 79515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gather Your Rosebuds", description = "Emberthal is quite troubled. It reminds me of a certain bronze dragon when she chose her visage form.\n\nNot to worry! Once Emberthal has returned, we shall throw a proper Visage Day celebration.\n\nThe fireworks are to match the colors of the dragonflights.\n\nEach enclave of the city grows special flowers in accordance with that enclave's flight.\n\nThree of each color should be enough for the first batch of fireworks.", progress = "We still require more flowers if we are to provide a celebration worthy of dragons.", completion = "Thank you, {name}. This should be sufficient.", objectives = "Collect 3 of each color of Flight Flower in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79521] = { id = 79521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seizing Evidence", description = "Councilward Merrix has authorized trade goods from the Deeps to be transported through this depot. However, we have received a tip that more than crafting materials are being sent and received here.\n\nDornogal observes strict rules about what we trade and with whom. All commerce must serve the Edicts, not the interests of individuals. We do not abide unsanctioned trading.\n\nWe have started going through the crates here to find smuggled goods, but we haven't found anything--yet. Help us take a look.", progress = "The tip we received was from a highly reliable source. There must be something here.", completion = "That is odd... These are very normal trading goods. There is nothing illicit here.\n\nThis is all you found?", objectives = "Collect 3 Seized Shipments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79522] = { id = 79522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Withheld Information", description = "There has to be something we're missing. The tip we received was from a very reliable source. We have no reason to believe we were being misled.\n\nThe Councilward will want us to get to the bottom of this, and I refuse to disappoint him.\n\nWe haven't been able to get any additional information out of the workers, but maybe you'll have more luck. \n\nSpeak to the ones we have detained here, and see if you can learn anything.", progress = "Someone here has to know something.", completion = "Ah-ha! False bottoms in the crates? Very clever.\n\nThat could be enough proof by itself to shut down this depot for good. But for the Councilward's records, we will need a full report of any smuggled goods we find.", objectives = "Interrogate 5 Line Workers to gather information on the shipments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79523] = { id = 79523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Hidden", description = "So, they have built extra compartments in the crates to hide extra items, eh? That explains how they have been smuggling goods into and out of Dornogal without our auditors knowing.\n\nExcellent work, {name}! But now the fun part of our job: those crates will have to be broken open and the smuggled goods taken into evidence.\n\nSmash the bottoms out of the crates and bring anything you find back to me.", progress = "Better luck this time, I hope?", completion = "<Kragad frowns as he looks over the goods you found.>\n\nSome of these goods are from Azj-Kahet... We are specifically forbidden from trading with the nerubians in any capacity. We cannot risk any resources falling into the hands of our enemies.\n\nThe Councilward must be informed.", objectives = "Smash 3 False-Bottomed Crates and gather any hidden evidence you find inside.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79525] = { id = 79525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to the Councilward", description = "Those receipts you found... Steelvein is a known smuggler that we've been chasing for a long time. The Councilward will be pleased to finally have solid evidence on his activities, and maybe even on his whereabouts.\n\nBring these receipts to Merrix immediately. He will want to study them in detail. He said he was heading back to his office, so you should be able to find him at the Councilward's Rise.\n\nI'll package up the rest of the evidence to be brought to him later. Good work today.", completion = "<Seems like there is nothing else to do but leave the receipts on Merrix's desk.>", objectives = "Take Steelvein's receipts to Merrix at the Councilward's Rise in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79526] = { id = 79526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sedition", description = "<The poster reads:>\n\nMERRIX is CORRUPT! STEELVEIN is WEAK!\n\nThey cannot protect the earthen! They do not care about them! They spit upon the Edicts!\n\nMERRIX was BRIBED to reopen Steelvein's smuggling operation! Steelvein HIDES behind MERRIX's authority!\n\nThey are taking from YOUR pockets to line THEIRS!\n\nDO NOT TRUST THEIR LIES!", completion = "Yes, I am quite aware of the situation.\n\nIt has rather disrupted my morning.", objectives = "Speak to Merrix at the Councilward's Rise in Dornogal.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79527] = { id = 79527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Damage Mitigation", description = "Obstorn has confirmed that Ardgrin, the overseer in charge of my supply line that runs from the Deeps into Dornogal, is the one who tipped off my peacekeepers.\n\nIt is therefore also my opinion that Ardgrin is the one who penned this sedition. He must have sent his workers upstairs to post them around the city.\n\nIt is imperative that we remove them before these rumors spread further. Tear them down for me.", progress = "I would not have these rumors spreading any farther than they already have.", completion = "Very good.\n\nThat will help stem some of the damage Ardgrin is trying to do to my reputation--both of my reputations.", objectives = "Tear down 8 Seditious Posters in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79528] = { id = 79528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dispelling Rumors", description = "Many of my peacekeepers have already caught wind of Ardgrin's sedition.\n\nI am told some are losing faith in my integrity as Councilward, believing that I have been taking bribes from smugglers to bolster my own coffers.\n\nI can provide proof that no such transactions have taken place--clearly--but we need to stop them from murmuring amongst themselves and giving the rumors power. Lies become truths through repetition.\n\nIf you find any discussing the matter, kindly disperse them.", progress = "I can assuage their fears later.\n\nFor now, we just need to prevent the situation from worsening.", completion = "I am pleased to hear that most of them were reasonable.", objectives = "Disperse 6 Murmuring Peacekeepers in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79529] = { id = 79529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forcing My Hand", description = "I do not know if Ardgrin merely intended to sabotage me or if he wanted to force a confrontation. Either way, a confrontation he will have.\n\nI believe this situation can be rectified peacefully, but I cannot do it as the Councilward. Steelvein has never appeared in the stone, but he must now. I will parlay with Ardgrin in the Deeps and this situation will be concluded.\n\nI would have you accompany me, but there are some things I want you to know before that. Help me prepare and I will speak with you.", completion = "I will have this solved peacefully.\n\nThough if Ardgrin asks for violence, we will answer.", objectives = "Help Merrix disguise himself as Steelvein.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79530] = { id = 79530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad Business", description = "I have not been to the Deeps since their machines shut down. Obstorn will have to guide us to Ardgrin's depot.\n\nOnce there, I will attempt a conversation. If Ardgrin is not amenable, which I suspect will be the case, we will respond with equal force. Our goal is to bring him back into the fold, not to beat him into submission. Ruling by fear only breeds resentment.\n\nWe will meet you in the Deeps. Come swiftly--and, of course, speak of this to no one.", completion = "Now that Ardgrin is willing to talk, we will talk. And all of this will be settled.\n\nYou have my gratitude, {name}.", objectives = "Meet Steelvein in the Ringing Deeps near Hallowfall Gate, then confront Overseer Ardgrin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79532] = { id = 79532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tinker, Tailor, Soldier, Spider", description = "I must thank you again for rescuing little Spindle from her predicament, my morsel. As a reward for your work, I would like to let you take loom and direct the weave of my newest tapestry.\n\nMeesk the Venomtongue threatens my weave-rats. He slanders my Queen. And he lends creedence to Ansurek's campaign of misinformation without a single thought to the consequences.\n\nI believe it is time that I sent Meesk and his ilk a message. Go into the city and find out as much as you can about our 'Venomtongue.'", progress = "Mm... Do hurry, my little morsel. I do not want little Meesk to run off before he has the chance to sample the fruits of his labor.", completion = "Kehehe... Indeed? I suppose I should not be surprised that someone as loose-tongued as Meesk holds a fondness for the underground's more banal pleasures.\n\nHe is prideful... And he is gluttonous. That should be more than enough for our purposes, I think.", objectives = "Gather rumors about Meesk the Venomtongue from the denizens of the Umbral Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79538] = { id = 79538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smelly Shrubberies", description = "Jenni here says she's got some creepers attackin' the goblins. I haven't seen any myself, but I do smell opportunity!\n\nWe've got our own anti-creeper perfume. It's the same recipe we use for the incense around town. Rub it on, and everything stays away! I'm sure we can sell some to the goblins.\n\nBut I'm out of materials--smellsage branches, specifically. If you gather some for me, I'll cut you in on the profits!", progress = "If you smell feet, you're in the right spot.", completion = "I could smell 'em the moment you came in! Those will work.", objectives = "Collect Smellsage bush branches for Rhubarn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79539] = { id = 79539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Electrifying!", description = "You wanna help the Venture Company? And you don't mind being disposable?\n\nOkay, listen up. When we moved in here, there were no monsters in town. But now we're finding dead workers, chewed up. It's bad for business.\n\nFortunately, I've got a way to make money off this: an electrocution helmet. I call it my Debugger Hat.\n\nTake the latest model for a test run outside town. Kill the bugs. The niffen will see you, see that Debugger Hat at work, and know it's got good reviews.", progress = "It oughta just kill 'em, but who knows? You might see other results, too.", completion = "So it had some extra effects? Great! The hype is real! What exposure! The orders will be pouring in!\n\nYou ever consider becoming a walking advertisement? Could have a bright future in making cash for me. For now, here's your wages.", objectives = "\"Advertise\" the Debugger Hat by hitting Noth swarmites with it outside of Mmarl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79540] = { id = 79540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Party's Over", description = "Nope, nope, nope!\n\nLook, I'm used to dealing with the additives in our swimming hole and keeping things at \"marginally safe\" levels, but spiders emerging to chew us to death? That's a hard pass from me. \n\nThis is OUR place, why are they buggin' us?", completion = "We put an incense beacon in there to keep bugs out. If the goblins changed it...", objectives = "Investigate the pool area in Mmarl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79541] = { id = 79541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn It With Fire", description = "So the goblins removed the incense the niffen used to keep those creepy pests out... because it smelled bad?\n\nHonestly, I'm not surprised. Maybe we can show them that they need to work together. Leading by example! Here, I'll lend you a flamethrower. I know mine works, without weird... chicken-like effects.\n\nHead in, clear out the nests, and put the right incense back in there!", progress = "The cave is just up ahead.", completion = "Okay, that flamethrower. I need it. I guess I'll talk to Gazlowe... but don't tell anyone that I did.", objectives = "Burn the Pillar-nest Hearts and replace the incense in the Mmarl cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79542] = { id = 79542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Councilward's Summons", description = "Councilward Merrix requests your presence in his office.\n\nHe received the documents you left and would like to discuss the Steelvein situation with you further.\n\n<Saradi regards you as if she is unimpressed. She also seems to be an earthen of few words.>", progress = "I am pleased you made it. The suspense was eroding me away.", completion = "Steelvein is a paradox in a city founded upon order and rules.\n\nPerhaps this presents an opportunity.", objectives = "Meet Merrix at the Councilward's Rise in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79543] = { id = 79543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dornogal's Benefactor", description = "You are in a unique position, {name}. A position to learn.\n\nYou met those who would bring this \"Bender of Edicts\" to justice, but what of the people of Dornogal? What do the earthen think of this Steelvein fellow? \n\nHumor me. Take the smuggled goods you intercepted and bring them to their intended recipients. Tell them the items are a gift from a \"mutual friend.\"\n\nYou might be surprised to learn who benefits from these... illicit deeds.", completion = "Harthan mentioned Ardgrin, you say?\n\nHe is a trade overseer from the Ringing Deeps. If he quarreled with Steelvein, that certainly concerns me.", objectives = "Distribute smuggled goods around Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79544] = { id = 79544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Security Through Trade", description = "If we're to solve this quarrel between Steelvein and Ardgrin amicably, then we'll need to make some new friends.\n\nOne of Ardgrin's employees, Obstorn, frequents a cinderbrew speakeasy here in Dornogal. Only Machine Speakers may enter it.\n\nEven as Councilward, I am not able to access it. However, there are others in the city who can.\n\nBevrusi, a Gundargaz trader, should be able to give you access. If you can grease her palm, she may be able to supply you access.", progress = "Do I know you?", completion = "So what do you say, surface-runner? \n\nYou polish my back and I'll polish yours. Do we have a deal?", objectives = "Convince Bevrusi to give you access to the cinderbrew speakeasy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79545] = { id = 79545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Market Reeve of the Forgegrounds", description = "I've heard liquid opal tastes remarkable but no matter how often I peruse the auctions here, it's never for sale. It's quite rare.\n\nLuckily for you, there is one person who can find the stuff. Vokgret, the market reeve of the Forgegrounds. Nothing circulates in the city's flow of trade without her knowledge.\n\nI don't often try to do business with one as... connected as her. But you'll have no qualms about it, I'm sure!\n\nAt this hour, you'll find her over by the inn.", progress = "<Vokgret speaks without looking up from her paperwork.>\n\nThe city certainly is a busy place.", completion = "Each corner of the Forgeground works in unison with each other like cogs in a machine.\n\nAll it takes is a single piece to fail to bring it all down.\n\nBut despite the disruptions, you have proven yourself resourceful.\n\nKeep this up and the right people will begin to notice.\n\nIf they have not already.\n\n<Vokgret peers at you over her spectacles and smiles.>", objectives = "Acquire a Vial of Liquid Opal from Vokgret.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79546] = { id = 79546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Machine Speakeasy", description = "Machine Speakers are odd and secretive units, some prone to paranoia. \n\nEven so, the grievance they have against Steelvein must be smoothed over.\n\nAs you have seen in the Forgegrounds, their quarrel with a single smuggler has put the entire city at risk. As Councilward, I will not stand for it.\n\nLet us go talk to Ardgrin's employee, Obstorn, and see if he can deliver a diplomatic message to his overseer in the Deeps.\n\nI will meet you in the tunnels.", progress = "I would have us exchange words, not blows.", completion = "I abhor violence, {name}.\n\nDissent. Desperation. Distrust. These are the consequences of ruling through fear.\n\n\n\nBut, sometimes, violence brings about clarity--and with it, revelations.", objectives = "Enter the speakeasy in the tunnels below Dornogal then confront Obstorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79552] = { id = 79552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hot Wax", description = "Oh. Fire bees bit bigger than Janky expect. Look mean.\n\nOther hives meaner, though. This best spot.\n\nYou go grab wax. Janky stay here to...supervise. Yes!", progress = "Is fire bee wax hot enough to melt self?", completion = "Yes! This make good candle, Janky sure.", objectives = "Collect 12 Fire Bee Wax from the Cinderwold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79553] = { id = 79553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Natural Remedy", description = "We stabilized most of the injured. But many of the earthen you saved need more help. Nerubians often fight with corrosive poisons that eats away even our stone bodies.\n\nFungarian flesh has long been used by our healers for its medicinal powers. The fungarian takeover of the quarry is one unexpected boon to our situation, one we will adapt to.\n\n<Adelgonn looks grimly proud.>\n\nOne we will adapt to. As the Unbound always do.\n\nBut I can't leave Ebona's side. Will you help me?", progress = "Please, hurry. The nerubian poison will deal irreversible damage given enough time. If it erodes enough of their frame or seeps into their memory gem... Then we may not be able to save them.", completion = "You brought back more than I expected. Thank you. Now, I will make the poultice.", objectives = "Collect 10 Fungarian Chunks in the Orecreg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79554] = { id = 79554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holy Hydrocarbons", description = "These devotional candles might be of interest to Janky the kobold candlesmith in Gundargaz.", progress = "What smell like new candle?", completion = "<Janky nibbles on one of the candles.>\n\nMhmm...mmm...fish oil...and touch of...sun blossom?\n\nInteresting technique, yes!", objectives = "Collect Devotional Candles for Janky in Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79555] = { id = 79555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep Wax Galactic", description = "While sourcing it may not be pleasant, this waxy substance seems like it might make a fine candle.\n\nJanky the candlesmith in Gundargaz might be interested in this.", progress = "What bring Janky?", completion = "Good bug wax, {name}! Make fancy bug candle out of this.\n\nScented, too!", objectives = "Collect Waxy Excretions and bring them to Janky in Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79556] = { id = 79556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Job Training", description = "Stoneheads use steam to run whole place. Have lava, have water, make sense.\n\nRepairs not going well, we hear. No new parts from factory. \"Against rules\" to use scrap, been told. A lot.\n\nHelp get old machines work. We watch, learn. Maybe not get yelled at for helping.", progress = "How go?", completion = "Seem easy enough. Put steam in pipe, try not to cook self.\n\nI get!", objectives = "Help Steamwarden Hurlt repair the steamworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79558] = { id = 79558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feathered Fiend", description = "The trinket appears to be a Noblegarden decoration of sorts. You should return this to the festivities at Razor Hill.", completion = "Well now, how did that go missing? Don't worry, I'll see to it that any stolen decorations are restored!", objectives = "Bring the Noblegarden Trinket to Sylnaria Fareflame at Razor Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79559] = { id = 79559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Verdigrease Knight", description = "Think you brave?\n\nBeen looking for brave, but not find much. Not sure you count, look like tenderfoot who run home to granny if scrape knee.\n\nHow about way to prove it? You hit me as hard as can. Try kill me.\n\nIf I not dead, then I get kill you, later.\n\nNot look like it take more than one chop for you.\n\nDeal?", progress = "Going to run away?", completion = "Hmm, sound like should have hit him harder. Always going on about knights not being brave enough.", objectives = "Slay the Verdigrease Knight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79561] = { id = 79561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord of the Giants", description = "Can tell you not new to questing. Fell many beasts in your time, am sure, like good knight must.\n\nGreasebaddaden, king of giant slimes, lair nearby. Perfect chance to prove valor to court!\n\nHas giant fork jammed in head, can't miss. You know what do.", progress = "Big, have fork in head. Know him when see him.", completion = "Return triumphant! Valor stick to you like reek of old grease.\n\n<Walkmay pauses, sniffing gingerly.>\n\nThat a lot of valor!", objectives = "Slay Greasebaddaden, King of the Giants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79563] = { id = 79563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lady of the Lake", description = "Shown great bravery. Humbility. Honor.\n\nWould make good Knight of Brown Table.\n\nOnly task left now is most sacred. Beseech Lady of Lake for blessing. She will judge whether worthy or not.\n\nLake in back of cave. More pond, really, but no tell her that. Puddle Lady not have same ring.", progress = "Not far, just in back of cave.", completion = "Only finest knights return with Lady's blessing.\n\nMost get lost somehow. Not far, really, so bit odd.\n\nStill, you make great knight, {name}. We sure.", objectives = "Gain the Lady of the Lake's blessing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79564] = { id = 79564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Verdigrease Knight Returns", description = "Am back, as promise.\n\nHear you now brave knight.\n\nReady fulfill your end of oath? My turn strike YOU down.\n\nKneel.", progress = "Make choice.", completion = "You show great courage today. Be proud.", objectives = "Kneel before the Verdigrease Knight and accept his reprisal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79565] = { id = 79565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Janky Candles", description = "With new candle almost ready, now all need is to set up stall! Bring quality candle at good price to people! That Janky guarantee.\n\nOnly problem is not have stall. You talk to Bosh in Gun-dar-ghaz for me? He have everything we need.\n\nMay need barter, but you talk good! Make him give parts.\n\nMeet you down there!", progress = "Got parts?", completion = "Good talking, {name}. Make great merchant one day.\n\nLike Janky!", objectives = "Acquire the parts Janky needs to build his stall in Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79573] = { id = 79573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[79574] = { id = 79574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Second Front", description = "Our reinforcements are already inbound. \n\nThese spiders just decided where our next wall will go. Clear a landing zone for General Steelstrike.", completion = "I will NOT risk the nerubians flanking us again. Their ambush is now our staging ground!", objectives = "Signal the landing zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79575] = { id = 79575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What the Duck?", description = "I cannot work under these conditions! Something has all these silly ducks in an uproar--they nearly upended my precious golden egg!\n\nThese chaotic quackers simply must be dealt with! I can keep them from entering the inn, but will you please help clear out the rest?", progress = "Shoo! Shoo! ...have you shooed them all yet?", completion = "Finally, a moment's peace! Thank you, {name}.", objectives = "Scare off 10 ducks using the Horn of Honking.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79576] = { id = 79576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fowl Concoction", description = "My egg! My precious egg! While I was shooing some stragglers away from the inn, a flock showed up and made off with some of our decorations and eggs. My beautiful golden heirloom was among the items stolen!\n\nEnough is enough. We simply must put an end to this duck invasion.\n\nPlease, {name}. These pilfering poultry must be stopped! Fortunately, I know a mage in Orgrimmar who might just have a solution for us.", progress = "Have you spoken with Tethris yet?", completion = "Don't worry, I'm sure he'll have a good solution. Wait here, I think I see a portal forming.", objectives = "Speak with Tethris Dewgazer at the Pathfinder's Den in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79577] = { id = 79577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duck Tales", description = "Take this potion, {name}. Drink it, and you should be able to chit chat with those feathery fiends.\n\nOh, but if you happen to experience any... unintended side effects, don't blame me.", progress = "Have they said anything interesting?", completion = "What? Some of the ducks are druids?\n\nThey won't get away with this!", objectives = "Use the potion to get information from 5 ducks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79578] = { id = 79578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just a Waddle Away", description = "We simply must find out where those ducks are hiding our stolen goods--and my precious egg! Oh, and who this mysterious Daetan is, of course. \n\nI convinced Tethris to give me more of that potion. Take it and bring back my golden heirloom!", progress = "Where would those ducks be hiding...", completion = "<Sylnaria carefully examines the golden egg.>\n\nUgh! Did a duck gnaw on this? My poor darling, don't you worry--we'll polish you up to a bright shine soon enough!\n\nThank you for your help, {name}.", objectives = "Discover the duck's hiding spot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79579] = { id = 79579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That Airspace is Mine(d)!", description = "Our advantage is air superiority. The nerubians are threatening that with their mines. \n\nYour mount is more maneuverable than our skiffs. Get in the air and take those mines out.\n\nI will deploy what resources I can to provide you some blessings to improve your capabilities.", progress = "Our priests are powerful with the Light but lack the air speed you and your resources can achieve.", completion = "Well done. The right weapon for the right front.", objectives = "Fly through 5 nerubian mines while under the effects of Holy Lance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79580] = { id = 79580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offensive Counter", description = "I will not yield this ground. \n\nGet out there and kill anything with more than two legs!", completion = "Well done.", objectives = "Slay 12 nerubians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79625] = { id = 79625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Quite Dead", description = "I am General Anub'azal.\n\nI loathe having little bipeds like you in the Siegehold. However, that is no longer up to me. Zev'kall is pushing me out of my own military stronghold, and collecting overcrawlers to boot! The Queen has deemed him High General, but he is unnatural, warped, and unfit. This will not stand! \n\nI have decided to use you and your kind against Zev'kall. And yes, you will get something out of it.\n\nSearch that rubbish pile there. You will see.", progress = "Go on, check the pile of rubbish.", completion = "I have plans for the both of you.", objectives = "Examine the spoils pile in Siegehold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79627] = { id = 79627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wine and Die", description = "I can see it now, morsel. The pattern of our newest weave is laid bare before my mind.\n\nMeesk is well-guarded. He believes himself to be safe. That is where his weakness lies.\n\nGo to the city. Procure a bottle of his favorite drink and present it to him as a gift from your benefactor. Once he is sufficiently wooed by your affable charms, bring him to the High Hollows for his well-earned reward.\n\nI trust you, {name}. And if you lay our threads out properly, I can guarantee you quite the show.", completion = "I've heard about you, overcrawler... Skittering about in our fair city and causing all sorts of trouble.\n\nI am glad that your superiors have finally recognized the value of having an ally like me in a place like this.", objectives = "Find a way to charm Meesk the Venomtongue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79628] = { id = 79628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emissary of the Council" }
quests[79630] = { id = 79630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Searching the Web", description = "Oh, thank the hollows! You look like someone that can help.\n\n<The nerubian dabs at her many eyes with a silken handkerchief.>\n\nIt's just horrible! Terrible! A tragedy! My husband has gone missing! We were just wedded yesterday! It was such a wonderful ceremony...\n\nBut when we were to retire for the evening, he disappeared.\n\n<She sniffles dramatically.>\n\nPlease, could you find him and bring him home to me?", progress = "Please, I need help!", completion = "Please help get me home!", objectives = "Locate Arax'ne's husband, Klaskin in the Umbral Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79631] = { id = 79631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klaskin's Great Escape", description = "Silken threads, I'm saved!\n\nIt's incredibly important that I make it back home without my wife seeing me.\n\nI took off after our wedding last night, and if she sees me, she's going to kill me! If the guards catch me, they'll surely alert Arax'ne.\n\nWill you help me avoid the guards and get back home?", progress = "Please hurry!", completion = "Wonderful! Klaskin, you are such a treat.", objectives = "Return Klaskin to Arax'ne in the Umbral Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79633] = { id = 79633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Weaver's Legacy", description = "Oh, this is exciting! A meeting with someone who commands even overcrawlers to do their bidding. I have been waiting for a moment like this.\n\nAh, I won't have to go too far though, will I? I am meant to host some up-and-coming Sureki socialites for dinner later tonight.", completion = "Make no mistake, {name}. I care nothing for Meesk's gratuitous proclivities. They were a convenient means of destroying him, but I am in no position to cast aspersions on matters of fickle morality.\n\nWe all scuttle about in the dark in search of that which gives us satisfaction. Meesk invoked Neferess' name for his own gain, and he put one of my weave-rats in danger. For that, he needed to suffer.", objectives = "Bring Meesk the Venomtongue to meet the Weaver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79636] = { id = 79636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emissary of the Assembly" }
quests[79641] = { id = 79641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wipe Away Their Smiles", description = "The kobyss grow bold if they feel they can defile our Veneration Grounds. I think we should collect their teeth to wipe the smiles off their faces.\n\nCome! My brother and I will cleanse our lands from this filth. Try to keep up!", progress = "Let's see them smile now!", completion = "A job well done, I think.\n\nAnd you managed to keep up!", objectives = "Collect kobyss teeth from slain kobyss.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79642] = { id = 79642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stave Them Off", description = "Without their magical weapons, the kobyss casters won't be able to use their foul necromancy.\n\nSteal their staves so we might toss them into the Sacred Flame and be done with them.", progress = "Did you find any Darkwater Staves?", completion = "Good job!", objectives = "Collect 5 Darkwater staves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79643] = { id = 79643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreaded Dreadfang", description = "My brother and I have dealt heavy blows to the kobyss, {name}, but you could have done more. \n\nThe most foul kobyss of them all has yet to taste my blade. If we take out their leader, the rest will flee back into the waters from which they came.\n\nLet's take the head of Dreadfang!", progress = "Ready to kill some kobyss?", completion = "No, please! Get up! ... Theleon...", objectives = "Kill Dreadfang the Merciless.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79644] = { id = 79644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go to the Priory", description = "I... I do not have the words. Theleon...\n\nI will take h-his body. They will know what to do at the priory.\n\nOh, brother... It was not supposed to end like this...", completion = "So young to have been taken from us. So brave and bold. Perhaps too bold.", objectives = "Meet Sister Etna Blayze at the Priory of the Sacred Flame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79645] = { id = 79645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweet-Sting Infestation", description = "Poor Theleon. I gave him some of his first lessons in combat. I'll see him to his final pyre.\n\nBut first, you. \n\nI've been trying to fight back an infestation of sweet-stings harassing our wine-making operations. I need someone else to finish them off while I tend to Theleon's remains.\n\nBe fast and clever and bring me some of their venom as you take care of things. We'll turn that into a poison for the nesting sites and be done with the nuisance.", progress = "Did you kill those things?", completion = "Good job! You hardly look stung.", objectives = "Collect 10 vials of Wasp Venom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79646] = { id = 79646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memorial Wine", description = "Oh, Theleon. He always did follow his big brother into anything. \n\nWhile we prepare Theleon for his final rest, would you please help Brother Abealard with a batch of Memorial Wine for the service?", progress = "Did you help Brother Abealard?", completion = "Such a shame we need to make so much of this wine.", objectives = "Make Memorial Wine with Brother Abealard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79647] = { id = 79647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Reflections", description = "Sybaestan could use your support now. His little brother was his best friend. Only death could separate them... and it has. He is not taking it well.\n\nIt is customary to burn written memories of the deceased. By committing them to the flames, we let go our heartache and let the warmth of memory heal us. It is a bittersweet time. You were with Theleon at the end, too. That might help Sybaestan.", progress = "The ritual helps ease the hearts of many.", completion = "It worries me Sybaestan's still in such anger over his grief.", objectives = "Help Sybaestan mourn his brother.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79648] = { id = 79648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Somebody", description = "Theleon was a good one, but now we must commit his body to the Flames.\n\nSybaestan is in no shape to bear his brother. Would you collect his remains from among those others awaiting their final rest?", progress = "You're strong and you have the distance Sybaestan lacks right now.", completion = "Gone? All the bodies are gone?!", objectives = "Collect Theleon's remains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79649] = { id = 79649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sacred Flame Inquisition", description = "All the dead are missing? How can that be? They were all laid out in preparation for their pyres. Who would want to move them? Someone must have seen something.\n\nGo ask anyone in the area who might have seen something and I'll go talk to some of the upper clergy. We'll get to the bottom of this and return our dead so they can be properly tended to.", progress = "Did you find anything out?", completion = "They attacked you? And said the Prioress is involved? That does not bode well.", objectives = "Interrogate the local clergy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79650] = { id = 79650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priory of the Sacred Flame: A Brother's Grief", description = "I fear that the Prioress may be behind our missing dead-- and our missing baron. Sybaestan has disappeared as well and I don't believe in coincidences. \n\nShe and Sybaestan have taken our recent losses hard. I fear what their overwhelming grief might be doing to their souls. We must confront them and bring them back to sanity... If we can.\n\nTell General Steelstrike what you have learned. We might need her backup. I'll be waiting for you here.", progress = "We must confront the prioress.", completion = "I wish it could have happened some other way... but at last they are all at peace.", objectives = "Confront Prioress Haelsey Murrpray inside the Priory of the Sacred Flame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79651] = { id = 79651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trade Partners", description = "Have you visited Mmarl? It's a trade town to the southeast of here. \n\nTry some of Corby's barbeque while you're over there!", completion = "Hey there {name}! Thanks for catchin' up with me.", objectives = "Check out Mmarl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79655] = { id = 79655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallowfall Arathi" }
quests[79659] = { id = 79659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Severed Threads" }
quests[79661] = { id = 79661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[79662] = { id = 79662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[79663] = { id = 79663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[79667] = { id = 79667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Elementary" }
quests[79669] = { id = 79669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Take Candle!" }
quests[79679] = { id = 79679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muddled Mind in the Mine", description = "The workers said they saw Munderut near the back of the mining area. Please find him and tell him that I said he needs to report back in. \n\nHe might not remember me, or that I am his fused. Tell him to look down at his chest, at the medallion he wears. His memory of our time together fades in and out these days, but the medallion tells of our story and bond forever.", completion = "Who are you? What are you doing here? \n\nActually, what was I doing here? Gathering spines, I suppose. I got distracted by all the elementals. They have made this area quite dangerous. I'm more of an artist than a fighter.", objectives = "Look for Munderut in Nibelgaz Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79680] = { id = 79680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pipe Patching", description = "Earthquake do number on old pipes. Many start leaking steam everywhere. Especially ones too tall to reach.\n\n<Fourman Grimes points up to the pipes stretching from Gundargaz to the surface.>\n\nStoneheads not have \"approved replacements,\" but we not have time wait.\n\nTake glue and seal leaks with flappy-flying thing. Made of only best bugs, boiled myself. Will do for today.", progress = "Try not glue self to pipe, yes?", completion = "See? Not need wait. Need action.\n\nYou understand.", objectives = "Fly near the leaks in steam pipes above Gundargaz to seal them with kobold-provided glue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79681] = { id = 79681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plumber Power", description = "Not all leaky pipes accessible from outside. Some inside tunnels run all under Gundargaz.\n\nTunnels small for stoneheads, but kobolds love tunnel! Just need someone to show layout. You, someone.\n\nCheck with crew boss if have problems. He help go over maps.", progress = "Get lost?", completion = "Job good. On to next.", objectives = "Use the Tunnel Access to plot the steam pipe routes through Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79682] = { id = 79682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Critical Pressure!", description = "Pressure still too high! Something else wrong, not just old pipes.\n\nOpen main release before something burst. Not have time for manuals.\n\nConsequences for deal with later!", progress = "Find problem?", completion = "Always something, {name}. Maybe old pipes behave now, yes?", objectives = "Open the main release valve and deal with whatever happens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79683] = { id = 79683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Is Where the Candle Is", description = "Exciting to have new place call home, {name}.\n\nNot quite settled, though. We not know Gundargaz. Gundargaz not know us.\n\nTime to fix both! Find out how help here. Teach new friends about us. Kobolds clever and friendly, so should be easy!\n\nStart with help three kobolds.\n\nFourman Grimes want get to work right away. She very task oriented.\n\nGranny Scribbles tell you lot about kobold culture.\n\nAnd Janky want set up new business in town, sell candle to Gundargaz.", completion = "Thank you, {name}. Have new home because you. Have future.", objectives = "Assist Fourman Grimes, Janky, and Granny Scribbles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79686] = { id = 79686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Concerning Fungarians", description = "<Abandoned in the dim candlelit chamber, the parchment, wrinkled and worn, bears the traces of hastily scribbled research notes.>\n\nLog Entry: 235-18-7\nDate: Fabrication Quarter Cycle\n\nObservation: Fungarians exhibit accelerated growth and increased territorial aggression. Spore dispersal seems to have quadrupled compared to previous recorded rates.", progress = "Did you find something interesting?", completion = "My notes! I was worried my research was lost forever!", objectives = "Collect the remaining research notes and return them to their owner in the Freywold Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79691] = { id = 79691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monsters in the Dark", description = "The local quarry was an active source of clay and ore for us until the fungarians took over some time ago.\n\nWe were worried about the fungarians encroaching upon the village, but there's something more.\n\nMultiple sightings of a creature much larger than our native wildlife have been reported at night.\n\nCombined with villager Modhina's disappearance, I fear this is no coincidence. She visited the quarry recently and hasn't returned.\n\nWe would be in your debt if you searched the tunnels.", progress = "You do us a great service by making our lands safe.", completion = "A stonestalker, here? Their habitat resides far beneath the isle's surface. All the recent change must be disturbing them.\n\nRegardless, thank you for slaying it. They are highly territorial and kill for sport.\n\nAs for the tunnels, the area sounds beyond recovery. We'll have to let nature reclaim it.", objectives = "Slay the Ashen Stonestalker in Gemvein Tunnels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79692] = { id = 79692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buried, Not Forgotten", description = "Several suns ago, my friend Modhina ventured into the quarry cave. She wanted to find rare ore for Hreka, to help her craftsmanship. Modhina was excited, I remember. A rare feeling for earthen.\n\nShe hasn't returned. The fungarians prevent us from searching the area.\n\nIt would mean a great deal to us if you could look for her. I didn't know it was possible to spend so much of the day thinking about what if's.", progress = "Be careful. I fear more sinister things lurk in these tunnels.", completion = "You've returned! Did you find Modhina...? What is all that you are carrying?", objectives = "Find Modhina and her belongings in Gemvein Tunnels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79693] = { id = 79693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Play Hearthstone!", description = "It's time to play Hearthstone! \n\nHere's a starter pack -- open it up and add those cards to you collection. Then, if you can find a seat at the game table, then sit down with someone else and play!\n\nOr if you can't find a seat, then you'll want some Wild cards.... I didn't tell you this but there's a shady card dealer lurking around here somewhere.", progress = "Like the game so far? Give it a chance and play those cards!", completion = "How did you do? Had some good, clean fun I'm sure!", objectives = "Play 5 Hearthstone cards at a Hearthstone Game Table, or Wild Cards NEAR a Hearthstone Game Table.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79694] = { id = 79694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Play Hearthstone!", description = "It's time to play Hearthstone! \n\nHere's a starter pack -- open it up and add those cards to you collection. Then, if you can find a seat at the game table, then sit down with someone else and play!\n\nOr if you can't find a seat, then you'll want some Wild cards.... I didn't tell you this but there's a shady card dealer lurking around here somewhere.", progress = "Like the game so far? Give it a chance and play those cards!", completion = "How did you do? Had some good, clean fun I'm sure!", objectives = "Play 5 Hearthstone cards at a Hearthstone Game Table, or Wild Cards NEAR a Hearthstone Game Table.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79701] = { id = 79701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cavalry is Here", description = "<Baelgrim quakes with fury.>\n\nThese cursed nerubians. Attacking a triage site! So many wounded and defenseless... and yet, it looks like you outlanders are putting up a fight!\n\nLet's grind every last one of the bugs back into the ground.", completion = "<Baelgrim is covered head to toe in nerubian ichor and blood.>\n\nGood work, {name}. Good, gruesome work.", objectives = "Repel the nerubian attack at the Proscenium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79703] = { id = 79703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hope, An Anomaly", description = "<Hreka looks through the things you retrieved, one by one.>\n\nSo you risked your life to find our friend.\n\nModhina is gone, then. Her notes are about the rare ore from the cave. Melted down, it becomes a beautiful glaze for pottery.\n\nWhat can I do? I'm no fighter. I can't avenge her. Besides, her body has already been reclaimed by the earth. That much is certain by the state of her memory gem fragment.\n\nWhat can I do now, but make a pot? Will you help me?", progress = "A lifetime spent making pottery. Is this my titan given fate? Then why do I still wonder?", completion = "Almost done. It needs a bit of time in the fire to set.", objectives = "Make a piece of pottery with Hreka.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79710] = { id = 79710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fin of Every Kind", description = "Oh! My! LEGS!\n\nYou're perfect! Yes! You're a perfect, little, unassuming biped for my work.\n\nAlchemy is my trade, and an alchemist is only as good as their ingredients. See these kobyss below? I've been camped out here for weeks observing them.\n\nThey seem tougher than average kobyss. My conclusion? They must be made of stronger stuff! And I want that stuff! \n\nHere's a sack. Fill it up! Fill it up with their innards! As much as you can carry!", progress = "Is that really as much as you can carry?", completion = "Brilliant! Fabulous!\n\nA sack brimming with promise, date, and... arterial goop.", objectives = "Fill up the Kobyss Innards Sack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79711] = { id = 79711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Pretty Gross", description = "<You dislodge a familiar-looking appendage from the silt.\n\nIt doesn't seem particularly kobyss, but perhaps a unique specimen will earn you an increased reward from Al'kubian.>", progress = "Ooooh! What is this?", completion = "You are what you eat.\n\nAnd these kobyss are eating the strongest nerubians ever to Ascend. \n\nDon't mind the marks of moisture on the ground... That's my anxiety sweat.", objectives = "Bring the Familiar-Looking Appendage back to Al'kubian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79713] = { id = 79713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonlight Gutter Swim", description = "An Ascended's leg...\n\nA kobyss tribe feasting one or two dozen trueborns or skitterlings, perhaps even a sageform such as myself... But an Ascended is a different story.\n\nLet us approach this as intellectuals, and use the tools at our disposal to collect more data. What tools do we have? You. You are the tool. An intellectual tool of kobyss disposal.\n\nDive into the lake's depths. Slay the largest of these creatures or their pets.\n\nAnd of course, bring me their innards.", progress = "Any profits I gain from my work goes directly to scientific and alchemical research.\n\nAs in, I use the profits for myself, and I am an alchemical scientist.", completion = "Ah, I must apologize. I realized I yet had another spare innards sack. It only dawned on me once you were away...\n\nThat aside--Well done. Good job. Impressive labors. So on, so on.", objectives = "Collect Liverseeker's Intestines and Leg Chewer's Stomach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79714] = { id = 79714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescuing the Food", description = "While awaiting your innards-bestowing return, I observed some fascinating activity below. A consistent train of kobyss are dragging the limp bodies of my kin from the lake's waters and westerly into their cavern.\n\nMy conclusion? Nerubians are being hunted and stored in the lake for consumption by these beasts.\n\nIt's not so much for research than it is for civic duty, but I would reward you might be able to save from their fate.", completion = "Your efforts are appreciated, but I will be rewarding these civic tasks at a... slightly lesser pay tier than your scientific ones.\n\nBlame my stipend.", objectives = "Rescue 5 Captive Kaheti.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79715] = { id = 79715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand, Gutsy Solutions", description = "I require one final piece of data.\n\nThese beasts think. They organize. They coordinate. To be characteristically honest, there's nothing worse than an amphibian with an abacus.\n\nMy final task for you: Bring me the brain of the biggest beast. I need it fresh, and preferably non-liquified.\n\nAnd, you know, perhaps it will slow them down as well.", progress = "Have you got it? Is it leaking?", completion = "Fabulous! Absolutely fabulous!\n\nUnrelated, the samples you've brought back are disgusting. I'm utterly appalled that you were willing to go without a sack again for the latter portion of our work together.\n\nYou should really wash your hands.", objectives = "Collect the Brain of Grand Gluttony.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79716] = { id = 79716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The History Beneath Us", description = "The titan console is a huge find. And look at these ruins! There has tae be more here!\n\nBut goin' out into the site is dangerous. Accordin' to Brinthe, now that the titan vault has been unearthed, elementals have come.\n\nElementals dunnae like order magic, an' titan relics just ooze the stuff. They're on a rampage!\n\nCan ye go out there an' get some relics back from the elementals? We need tae preserve what we can!", progress = "Have ye found anythin' yet?", completion = "Look at all these relics! \n\nLook at all this history!\n\nAnd tae think... the elementals were just goin' to destroy it.\n\nI could cry, I could!", objectives = "Collect 20 Shattered Relic Fragments from elementals in Golgrin's Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79717] = { id = 79717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Means of Ingress", description = "Ah, look at you! Just the sort of rogue element I need.\n\nMy name is Ar'syn, and I am something of a connoisseur for the fine arts and histories of our people. It is my intent to enter the Royal Preservatory--that's that large enclave just over there-- and rob it blind.\n\nBut gracious, the guards will never let me get close enough to survey their security! If only I had someone to help me find a somewhat more subtle way into the building.\n\n<Ar'syn looks at you meaningfully.>", progress = "Well, what do you think? I think you'll find that even the Preservatory itself is quite the work of art in its own right... Though that does mean it will prove rather vexing to infiltrate.", completion = "Say what you will about our new queen, but she knows how to run a tight ship. They are ferrying their spoils of war into the building at a remarkable rate.\n\nBut then, that may well be your ticket inside.", objectives = "Survey three potential entryways into the Royal Preservatory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79718] = { id = 79718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skeins Street Irregulars", description = "I would like nothing more than to go in and take a few of these pompous Sureki royalists out. It would make our infiltration that much easier, and it would serve them right for trampling upon our history. But I cannot get close without bringing a whole host of guards down upon the Skeins.\n\nYou, though? No one will bat an eye at wanton violence if it comes from an overcrawler. Why not get in there and thin them out a bit?\n\nOh, don't give me that look. You were going to do it anyway.", progress = "You needn't worry about any moral quandaries here. The craven Sureki would do the same to you thrice over.", completion = "I'll be honest, friend. I find brute force somewhat lacking in artistry.\n\nBut goodness, you make it into a performance piece unto itself! Color me impressed. And a bit intimidated.", objectives = "Slay Sureki agents around the Royal Preservatory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79721] = { id = 79721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire in the Hole", description = "Who are you? But of course, another outlander! I'm Wenbrandt, tamer of cinderbees and creator of cinderbrew.\n\n<Wenbrandt squares himself up as if you should be impressed.>\n\nI had brought barrels of cinderbrew to help the injured. I thought drinking it would ease their pain, but for most it just caused more... burning... pain...\n\nI refuse to let my brew go to waste. Maybe it can be weaponized. The nerubians are just bugs after all--organic and flammable.\n\nThis burrow here is a perfect test subject.", progress = "Go drop a few on the nerubians. Let's see what happens.", completion = "Mountains fall on me, that was incredible! And to think that we've been drinking the stuff...", objectives = "Use cinderbrew to repel the nerubian attack in the Proscenium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79722] = { id = 79722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutter Work" }
quests[79723] = { id = 79723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repatriation by Subtraction", description = "Ansurek and her ilk are so short-sighted. They think that by filling our museum with trophies of their recent conquests instead of relics of our own history, we will be less inclined to remember where we came from.\n\nWell, they are probably right--in the long term, at least. History has a habit of bending towards the voice of its teller.\n\nBut that is where we come in, {name}. Those relics that the Sureki forces stole? It's time to steal them back.", progress = "Well, {name}? I'm sure the place is filled with a queen's ransom.", completion = "<Ar'syn's many eyes sparkle in the cavelight.>\n\nThough my goals today are on the philanthropic side of things, I must profess my appreciation for a good heist well-executed. Look at all of these treasures! I do so look forward to returning them to their rightful homes.\n\n...For a finder's fee, of course. Imagine if Azj-Kahet's legendary legerdemain became some sort of folk hero?! Ugh, the very word sours on my tongue.", objectives = "Loot six Pillaged Trophies from the Royal Repository.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79724] = { id = 79724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Titanic Expedition!", description = "Our merchant friend told us about some small islands off the northeast coast called \"The Three Shields.\"\n\nApparently, there was a lot of titan activity there long ago. To me, the \"activity\" sounded like titan research and development. Exciting stuff!\n\nTuberros and I are going there to check it out. Tharessa, my new Algari Expedition trainee, is coming along to see true professionals at work.\n\nCare to join us?", completion = "All right, I'm fine. It's just a scratch. \n\nBut it took the three of us to bring down one little gorloc, so it's good you decided to join us.", objectives = "Meet Rannan at The Three Shields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79725] = { id = 79725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not a Heating Pack", description = "Tharessa has done some reconnaissance for us and found the gorlocs are digging up artifacts and... cuddling with them. \n\nI think it means that the artifacts emit heat? Maybe that means some artifacts are still functioning?\n\nImagine--the titans created technology to shape worlds, and now a fish uses it to warm their fins. Hah!\n\nThe gorlocs won't give them up, and I don't want to be a Rannan-kabob either. I hate to ask because they just want to be warm, but could you do something about them?", progress = "Did you get them? I thought I saw one sneak by a moment ago...", completion = "Wonderful! Now we can focus our attention on what really matters--the artifacts. I wonder what we will discover?", objectives = "Rannan wants you to kill 12 gorlocs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79726] = { id = 79726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Cataloguing\"", description = "As ya know, we are here to collect some titan shinies, artifacts, whatever!\n\nAnd Rannan thinks the more shinies--er, you know what I mean--the better chance we have figurin' out something about the titans.\n\nThat'll make Rannan happy, but it'll also ensure I have some extras to take to my store back home.\n\nMy wife, Perisimona, is waiting for 'em back in Loamm. I can't go back empty handed!", progress = "You get some good shinies yet?", completion = "<Tuberros looks at the titan artifacts.>\n\nThis one smells very acidic--and it's broken. I can take it to the store... Rannan would like to see that one... Oh yeah, these are great. Thank you for bringing them to me.", objectives = "Recover 7 titan artifacts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79727] = { id = 79727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Because It's Shiny", description = "While these two were ordering you around, I thought I would do something useful and make sure the gorlocs were not going to surprise us here on the beach.\n\nNone of them seemed interested in us, but then I saw one huge gorloc.\n\nIt killed off some smaller gorlocs then took off. It had something glowing in its claw though!\n\nIt had to be an artifact. And it looked like it was working! We've got to get it back.\n\nBy \"we\" I mean \"you.\" Larger-than-average gorlocs are above my Dragonscale pay grade.", progress = "Were you able to get the artifact?", completion = "I can hear it humming from here. Ow. It irritates my ears.\n\nLet's see if our two \"professionals,\" Rannan and Tuberros, know what this artifact is.", objectives = "Retrieve the artifact from the huge gorloc.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79728] = { id = 79728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Probably Nothing", description = "You found a buzz orb! \n\n...Er, that's what the niffen call it. I just kind of went with it. \n\nIt's still in a good condition. Still buzzing, humming, and warm to the touch! I haven't seen one since we were in Zaralek Cavern!\n\n{name}, you should see if we can get it to work. I will stand back here, just in case it is, um, not friendly. \n\nNothing to worry about, I'm sure.", progress = "Yes, yes! It will be very exciting to hear what you have discovered.", completion = "Alpha site? Defense grid?\n\nI don't like the sound of that.\n\nWe should get going. I don't want to be here if its friends come back with it.\n\nThat's not a reunion party I want to be a part of.\n\nHopefully it won't hone in on Tharessa... Nah, probably not. Anyway, we should get going. Like now.\n\nCatch you later, {name}. Thanks for your... um, help? I guess?", objectives = "Interact with the titan orb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79729] = { id = 79729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Educate Yourself", description = "The Relics of Founding have always been the centerpieces of the Preservatory's collection. Together, those four artifacts tell our most reverent tale--that of the founding of Azj-Kahet, and of our people's rejection of our Old Masters.\n\nWith luck, they will still be inside the Preservatory. Once you are inside, I want you to tamper with the shadecasters in front of each of the relics. Make sure that their messages are heard by anyone nearby--whether they wish to listen or not.", completion = "And there we have it. A brilliant calling card to suit our schemes, and an excellent distraction to cover our escape. All in one convenient, educational package!\n\n...Would that it were all good news, however. Our exit strategy has grown complicated.", objectives = "Tamper with the shadecasters in front of each of the four Founding Relics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79730] = { id = 79730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dogged Pursuit", description = "But of course, simply stealing the relics isn't enough. We need to teach the Queen's pet burrow-worms a lesson in futility, or they will simply start the whole process again!\n\nThat shouting buffoon near the central passage is Rez'kal, a member of Ansurek's personal academic entourage. He's... not very bright, but he makes up for it with enough strength to send either of us through a wall.\n\nI'm not inclined to go toe to toe with the big oaf today. Would you mind overmuch doing one last favor for me?", progress = "Be careful, {name}. What Rez'kal lacks in acuity he makes up for in scarab-headed stubbornness.", completion = "Ah! There you are. Fine job back there with the lummox. He may have been a buffoon, but he was a buffoon with very sharp blades on his arms.\n\nNow, with relics in hand, it is time for me to make my grand exit. I've a great many pilfered riches to re-appropriate, after all! I've truly enjoyed our time working together, though. Perhaps, with luck, our paths will cross again soon.", objectives = "Defeat Royal Broker Rez'kal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79944] = { id = 79944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raging Rifts", description = "The elementals are coming from inside that cave. We only made it part of the way in before needing to retreat. \n\nI could see some flickering within, some strange glowing thing that looked almost like a tear in space from which the elementals poured forth! We managed to close one of these portals, but there are more.\n\nI need to stay with Nanthaz. It is up to you now, if you can manage. Destroy the rifts and find their source. I suspect it lies deeper within the cave.", progress = "Destroy what rifts you come across, but above all, find their source! I suspect you will find it deep inside the nearby cave.\n\nThe miners you rescued spoke of breaking through to a crystal-filled room, and of the elementals pouring forth from within.", completion = "You return with good news, I hope? \n\n<You tell her about Urthgrafr Riftcaller.>\n\nWith Urthgrafr's defeat, we should have no problem cleaning up the rest of the elementals and rifts ourselves. We are lucky that you came along when you did.\n\nThank you for your help, friend. Do not worry about me or Nanthaz. We will make our way back to the refinery once he has caught his breath. Gratitude, outlander. And may all earthen Awaken one day.", objectives = "Destroy 4 rifts and find their source within the cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79954] = { id = 79954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiders!", progress = "Don't let the spiders eat you before you escape with my key.", completion = "I don't want to hear about where you found it, I have no need for the details.\n\nI am very excited to move into my High Hollows burrow!", objectives = "Find Ag'thax's missing key in Pillar-nest Xesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79955] = { id = 79955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...And Now I'm Arachnophobic", description = "Who is there? Someone? Did I imagine you?\n\nI am Albert. I was a Pathfinder once. Now that I'm blind, I see no path. It seems wrong to call myself Pathfinder Henson. I can hear, though. I can hear them eating. They eat the fresh parts.\n\nMy eyes. My insides.\n\nIt hurts all the time. They do not want my rotten pieces. The decayed parts are all I have left. The worst of me. \n\nI wasn't alone here, I had fellow Pathfinders. I keep hearing sobbing from the walls. Do you hear them too?", completion = "They are dead, then...", objectives = "Locate Albert's friends in the walls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79956] = { id = 79956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legs in the Ceiling", description = "I don't require vengeance on my behalf, but I would like vengeance for all of my friends that were eaten. I didn't think the Horror of Xesh was real, but she is. Xishirra. A shadow of a nightmare, making a brood of monsters while she stays out of reach.\n\nThe horror is ancient, and beyond us, but we can still make her pay! Pull hard on a web strand if you need to, and deal with whatever comes. We'll escape after some justice is had!", completion = "<Albert's eyes were already dark, but any spark of life has faded from the rest of him, as well.>", objectives = "Pull on the spider thread if the spiders are not already attacking, and kill whatever comes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79957] = { id = 79957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maggots in your Eyes", description = "<Albert is no longer alive. All that remains is his head, still full of maggots.\n\nTaking him back to the Pathfinders seems like the right thing to do.>", progress = "Whose head is that?", completion = "This eyeless, mostly eaten, maggot-infested head is...\n\nAlbert! Oh no, what happened?!\n\nWe didn't know where his team had gone, just that they'd taken a mission near the city.  I can't imagine the trauma he endured, or what you had to do to bring his remains to us. We'll take it from here. Thank you for bringing him back.\n\nAnd I hope the nightmares that could come from this don't linger for you, friend.", objectives = "Take Albert's head to the Pathfinders in Faerin's Advance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79958] = { id = 79958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worm Sign, Sealed, Delivered" }
quests[79959] = { id = 79959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wormcraft Rumble" }
quests[79960] = { id = 79960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking it To Go" }
quests[79965] = { id = 79965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn the Ropes or Walk the Plank" }
quests[79988] = { id = 79988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gateway to Somewhere", description = "The enchantment will protect us from the unstable energy contained within.\n\nI will open the way to the nearest stone. \n\nOnce you pass through, stay close. I shall need your assistance when we arrive to power up the device.", sourceObjective = "Follow Warpcaster Delandra to the Waygate's location.", sourceObjectiveStatus = "unverified-source-field" }
quests[79989] = { id = 79989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ancient Awakening", description = "The waygate sits just behind me. There is no way to tell how long we have until the waning enchantment on this vessel fades, or even worse, breaks.\n\nThat amount of unstable energy being released could be catastrophic. \n\nShall we continue?", completion = "Now that we, and by we I mean you, have figured out what these things are fer there's no tellin' how many more are out there!\n\nKeep yer eyes open, {name}. No tellin' what we might find around the Isles.", objectives = "Empower the Waygate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79998] = { id = 79998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mite Not Right", description = "This not good. Fancy fire bees have mites!\n\nJanky seen this before. Hive get infested, good bugs get sucked dry. End bad. Need do something!\n\nBlast bees with smoke. Makes bees sleepy but mites hate!\n\nWhen jump off, you squish before they bite bees again.", progress = "Many mites left?", completion = "Only good mite, dead mite. Good job.", objectives = "Cleanse fire bees of their infestation with Janky's scented smoke and kill the offending mites.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79999] = { id = 79999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Igniting Hope", description = "One dawntower has fallen, but a faint glimmer of hope remains with the smaller keyflame atop the wall. \n\nThe shattered remnants needed to sustain that light were taken by the nerubians.\n\nGather the remnants from nerubians you slay, and help ignite a beacon of hope!", progress = "An empowered keyflame will be a great help.", completion = "With the light of the flame I see hope that we will drive the nerubians back!", objectives = "Gather 5 Shattered Remnants and use them to empower the Aegis keyflame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80000] = { id = 80000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beebiter", description = "Mites kill fire bees. No good!\n\nJanky hate mites. Bite you when not even stealing wax. Not even make wax!\n\nGive bees chance. Kill biggest, bite-iest mite before eats more bees.", progress = "How feel about being on fire? Good?", completion = "Fire bees safe now. Be here when come back later for more wax.", objectives = "Slay Beebiter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80004] = { id = 80004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crab Grab", description = "<The arrival of the kobyss has kept the Arathi from working these shores. Delivering a cage full of fresh crabs could aid citizens in need of food.>", completion = "Thank you {name}, this is an unexpected surprise!", objectives = "Collect 12 Shadowtide crabs from the waters off the Faded Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80005] = { id = 80005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crab Grab - Activate" }
quests[80012] = { id = 80012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skyriding", description = "This land is more vast than I remember. However, a good scholar always prepares for contingencies.\n\nTwo of the most airborne dragons have agreed to aid our cause. They will provide a winged mount so you may cover more ground.\n\nI will send you to Lord Andestrasz. He shall instruct you further.", progress = "All things come with practice.", completion = "Let us get started.\n\nDo not worry, the fancy maneuvers will come later.", objectives = "Take Moratari's portal to Lord Andestrasz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80013] = { id = 80013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Glide with Your Dragon", description = "Let us start with the basics.\n\nIf you fly straight you will wear yourself out right now. Use gravity as an aid and aim slightly down to fly a long distance. The rings will give you the general angle that you should use for basic gliding.\n\nFirst, call upon your drake, or our Red Drake friend here can give you a lift.\n\nThen, fly through the rings and land at the target location.\n\nIf you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", progress = "Well done, {name}.", completion = "Excellent work!", objectives = "Summon your dragonriding mount, or mount the Red Drake. Then glide through the rings and land in the target area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80015] = { id = 80015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Dive with Your Dragon", description = "Gliding will get you to where you want to go. But what if you want to get there faster?\n\nDiving after jumping from somewhere high will give you a speed boost. As long as you fly well, you can conserve your momentum and gain some height after a dive.\n\nFly through the rings to the target location.\n\nIf you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", progress = "Well done, {name}.", completion = "See? That was much better.\n\nIf you start your flights with a dive you will get to where you want to go so much faster.", objectives = "Dive then glide through the rings and land in the target area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80016] = { id = 80016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Need For Higher Velocities", description = "Sometimes you'll need to travel longer distances.\n\nIf you don't need to travel up and over any obstacles, using Surge Forward is the easiest way to maintain a good forward speed to prevent yourself from plummeting out of the sky.\n\nFollow the rings again to your destination and use Surge Forward when prompted to maintain your speed.\n\nIf you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", progress = "Well done, {name}.", completion = "Well done. The rest is now a matter of practice.", objectives = "Fly through the rings and land in the target area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80017] = { id = 80017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Need For Higher Altitudes", description = "To gain height, use Skyward Ascent.\n\nFollow the rings again to your destination, using Skyward Ascent when you need upward momentum.\n\nIf you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", progress = "Well done, {name}.", completion = "Ever upward you shall go.", objectives = "Fly through the rings and land in the target area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80018] = { id = 80018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fashionable Flying", description = "You have learned all I can teach you.\n\nBut flying isn't just about getting to your destination--it's about getting there in style!\n\nUse the Rostrum of Transformation behind you to customize your drake's appearance.", progress = "How do you like your look?", completion = "Now you are ready to fly.\n\nOff you go, best of luck on your journey!", objectives = "Use the Rostrum of Transformation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80022] = { id = 80022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calling the Stormriders", description = "I know the Unbound can repair and unblock the Coreway expediently--but I also know the nerubians. If they see an opportunity for an ambush, they will take it.\n\nWith our backs turned and our focus on the Coreway, we are prime targets.\n\nI need to rally my Stormriders and form a perimeter around Dornogal in case of an attack from within or from without.\n\nMeet me outside of the Stormperch. I will call upon my troops there.", progress = "Baelgrim is right. We need to defend the Unbound while they work on the Coreway.", completion = "The entire Rookery?\n\nI see.\n\nAt least the source is destroyed. I lament the loss of so many Stormriders but...\n\nIf the corruption had spread to Dornogal...", objectives = "Meet Baelgrim outside the Stormperch, then speak with him to follow him into The Rookery.\n\nThis challenge may be completed solo or with up to 3 party members.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80049] = { id = 80049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flame Still Burns", description = "That was too close.\n\nThis attack took a toll on all of us. We have many injured, and many shaken. \n\nCan you check in with people? See how they are doing?", progress = "How's it looking out there?", completion = "The Arathi spirit can never be broken!", objectives = "Check in with Arathi Survivors in the Veneration Grounds in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80058] = { id = 80058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kobold Kleanup", description = "New home little shabby. Not good, full of fun stuff and good bits shabby. Old, everybody died and now it fall apart shabby.\n\nWe help! Lots of kobolds, now, so we make place presentable for stonehead friends. Make feel like home.\n\nYou help, too. Grab broom, get going!", progress = "How go?", completion = "Much better. Lizards tasty, but not want running all over nice rugs.", objectives = "Clean up Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80069] = { id = 80069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tears of Teldrassil", description = "I have carried this weight long enough. It has finally come time to put my family to rest. Even if I never found my sister...\n\n<Kelestra wipes away tears and takes a deep breath.>\n\nI must gather barrowstones to place at their final resting place. But I simply cannot carry that many stones.\n\nMaybe I ask too much of a stranger, but would you assist me? I know having someone beside me will make this more endurable.", progress = "<Kelestra looks distraught, and her hands are shaking.>\n\nI can not parse my feelings. My sister is alive, but a traitor.\n\nAnd what did he mean she deserved her fate?\n\nPlease Koroleth, let this finally be our time to reunite.", completion = "<Kelestra takes a deep breath and tries to calm herself.>\n \nKoroleth... what have you done? Why? I must find out why!", objectives = "Follow Kelestra and collect barrowstones to help her memorialize her family.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80071] = { id = 80071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fact Finding", description = "I must speak with the Primalists. I don't understand why she would turn her back on us.\n \nKoroleth saved my life at Teldrassil. I owe it to her to find out the truth.\n \n{name}, I realize this might be awkward, but will you help me? I can no longer bear this alone.", completion = "Thank you for coming {name}.", objectives = "Meet Kelestra at the Twilight Watchtower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80072] = { id = 80072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Primalist Point of View", description = "Warden Malathra has granted us permission to speak with the Primalists. They might have switched sides, but the wardens are keeping a close eye on them.\n \n<Kelestra begins to look distressed.>\n \nI'm going to talk to the Warden more. Could you handle the Primalists? All of this about Koroleth is just happening so suddenly. I feel we should gather as much information as we can.", progress = "I want to talk to them, but I don't even know where to begin.", completion = "What were you able to find out?\n \n<Kelestra listens as you explain what you learned.>\n \nI can understand why my sister would want nothing more than the Horde destroyed. I and many others felt the same way for a time. And Koroleth always had a single-minded focus in getting what she wanted.\n \nBut I also believe that had she known about Amirdrassil, she would have defected immediately.", objectives = "Speak to the reformed Primalists about Koroleth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80073] = { id = 80073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bones of a Bygone Battle", description = "After speaking with the warden, I learned the Battle of the Barrier where my sister fell took place east of here, on the shores of the Ohn'ahran Plains. \n \nI understand her body was washed out to sea and never recovered.\n \nIt's possible the tide brought her remains back to shore at some point. Will you help me look for her? \n\nEach member of my family has a necklace with this distinct design. It will identify Koroleth's body.\n\nI would like to lay her to rest with the family she loved.", progress = "Is this the necklace you found?", completion = "Oh Koroleth...\n \n<Kelestra looks at the remains and weeps softly.>", objectives = "Search the shoreline of the Ancient Bough for Koroleth's remains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80075] = { id = 80075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Barrow Den Burial", description = "All that is left to do is to gather my sister's remains and bring them to the barrow den. \n \nPlease meet me there, {name}. I could use a friend.", completion = "<Kelestra is on the verge of tears.>\n\nThey refuse to let me in. After all we have done. They deny my sister peace!", objectives = "Meet Kelestra outside the barrow den at the Fields of Reverie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80077] = { id = 80077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sins of the Sister", description = "This druid is trying to convince Malfurion not to let me bury my sister here with the rest of my family. He won't even let me get a word in.\n \n<Kelestra tightly clutches the straps of her backpack holding her sister's remains.>\n \nI know I have asked a lot of you already. Could you talk to them? Perhaps they might listen to you?", progress = "<Malfurion is deep in thought.>", completion = "That was no easy decision to make. But I believe it was the correct one.\n \nThank you for assisting Kelestra in this matter. Despite the circumstances, let us hope that finding her sister may give her some measure of closure.", objectives = "Speak with Malfurion Stormrage about Koroleth's remains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80079] = { id = 80079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wrench in the Works", description = "Looks like the High Speaker is addressing his workers.  It seems something has finally shaken them from their complacency, and their time away from the Awakening Machine is affecting them.\n\n<Moira pauses to brush a bit of dust off her robe.>\n\nPerhaps this would be a good opportunity for everyone to hear what they have to say?\n\nWe should convince a few of these Machine Speakers to speak up.", progress = "Recalcitrant lot, aren't they?", completion = "Excellent, now we're starting to make some progress.", objectives = "Encourage members of the crowd to air their grievances.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80081] = { id = 80081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain's Orders: Flood and Plunder" }
quests[80082] = { id = 80082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Gundargaz", description = "We may not have overthrown the Candle King, but our work here has surely relieved some of the pressure facing Gundargaz. And it's made us more than a few new allies, as well.\n\nOur new friends will not be forgotten, on my word as Speaker. There is a...regrettable amount of available housing in Gundargaz as of late. It will be nice to feel the city come to life again, and we can certainly use the manpower.\n\nShall we bring them home, {name}?", completion = "I'm glad to be back, but this gathering is... troubling.\n\nLooks like discontent is growing.", objectives = "Return to Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80096] = { id = 80096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shovel in the Stone", description = "Now, friend, we quest for blade of legend! Whoever pull from stone it stuck in destined for greatness.\n\nOnly problem is that it very stuck. In very big rock. No idea how even get there, really.\n\nCome! We try you hand at fate!", progress = "Pull with knees, not with back.", completion = "You destined for great things, {name}. Shovel is proof!", objectives = "Recover the legendary kobold shovel Excavator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80110] = { id = 80110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Doubloons" }
quests[80144] = { id = 80144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Holey Grail", description = "Holey Grail, one of very best relics, lost for long time, {name}. Very old, very powerful.\n\nWould mean a lot if could find.\n\nSet you grand quest to search for Holey Grail!\n\nTry start with Fishcan. He old as dirt, might know something. Seek him by pools to north-east.", progress = "Got Grail?", completion = "Even hole-ier than remembered. More fish goo, too.", objectives = "Find the Holey Grail.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80145] = { id = 80145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Motherlode", description = "<Zee-Zee's internals begin to hum softly as their projector reaches the appropriate operating temperature.>", progress = "<Zee-Zee looks up at you.>", completion = "<Zee-Zee looks ready to head back to the Deepforge Golemworks.>", objectives = "Activate the remaining crushers in the Shadowvein cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80175] = { id = 80175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Mage", description = "I want you to check in on someone. He's a mage... the only one of us who is. All the others died in the crash.\n\nHe's trying to make a portal to the Empire, so we can get reinforcements and have a way to and from home. \n\nWe all know it's a lost cause, but he still hasn't given up. \n\nMaybe meeting a seasoned traveler like you will give him the reality check he needs. Check on him, will you?", completion = "What? Who sent you? \n\nIt doesn't matter, listen! I'm so close to a breakthrough I can taste it!", objectives = "Find Wenren Althal in Beledar's Bounty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80176] = { id = 80176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Trickles", description = "I've almost got it!\n\nI'm making a new kind of teleportation spell to get us back home to the Empire.\n\nThese crabs might just be the key. They're practically radiating arcane teleportation magic!\n\nI need more samples to study. \n\nTake this focus, it will let you see traces of the arcane. There aren't many other arcane sources around here, so any you see should lead you straight to the affected crabs!", progress = "Have you found the crabs? They'll be near water. That focus should let you see the trails of arcane dust they leave behind.", completion = "Yes, these are perfect!", objectives = "Obtain 5 Arcane-Suffused Organs from Shore Crawlers near Mereldar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80177] = { id = 80177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Experiments", description = "This is it! The energy crackling from these crabs is charged with teleportation magic! I just need to extract it and adjust the formula--\n\nI can do this, my new friend! I just need another hand. Help me test this?", completion = "<Wenren's lifeless eyes stare up at you.>", objectives = "Help Wenren with his experiments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80178] = { id = 80178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Murder Most Foul", description = "<Somebody didn't want Wenren to finish his spell.\n\nFind out who.>", progress = "<The body is still warm.>", completion = "<You carefully consider the clues you have gathered.>", objectives = "Investigate Wenren's murder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80179] = { id = 80179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Justice", description = "<The pieces fit together to form a simple, but dark picture.\n\nThe Order of Night did not want Wenren to create a portal back to the Empire. No doubt reinforcements and supplies would hinder their mission. \n\nSo, someone stabbed him, burned his research, and smashed his tools. \n\nBut with this arcane focus in hand, you can see a faint trail of arcane residue. Did some arcane dust get on the perpetrator? \n\nFollow the trail and find out.>", completion = "<Steelstrike listens to your story with growing concern.>\n\nNo! Dead?!", objectives = "Track down Wenren's killer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80183] = { id = 80183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pieces of Hate" }
quests[80184] = { id = 80184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserving in Battle", description = "There is much to learn on the battlefield, even in lesser coordinated environments. Go ahead and give it a try.", progress = "You haven't finished quite yet.", completion = "See, it wasn't so bad. Take this for your time.", objectives = "Obtain Honor in Random Battlegrounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80185] = { id = 80185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserving Solo", description = "Battling on your own will build strength and courage. Display your solo capabilities in small battles, then return to me.", progress = "Finish off what you set to do then return.", completion = "Your nobility and strength is clear. Take these.", objectives = "Complete 12 rounds of Solo Shuffle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80186] = { id = 80186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserving in War", description = "Partaking in large-scale conflicts will hone your ability to look at the larger picture. Go off and garner that experience, then come back to see me.", progress = "Complete what you have set off to do.", completion = "I knew you would succeed. Here, take this.", objectives = "Obtain Honor in Epic Battlegrounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80187] = { id = 80187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserving in Skirmishes", description = "Part of training is repetition. I am told there are others out there like yourself that partake in small-scale skirmishes. Go off and find training partners to battle against, then return to me.\n\nLet us see what you can prove, then return to me.", progress = "Practice makes perfect. Finish off the tasks then return.", completion = "Excellent practice! Here's something for your time.", objectives = "Obtain Honor from Arena Skirmishes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80188] = { id = 80188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserving in Arenas", description = "Fast paced and coordinated combat is a mighty test for the strongest combatants. Find others to battle alongside you to fight worthy opponents in the arena.", progress = "You have not finished what you set off to do yet.", completion = "Very impressive - take these as your reward.", objectives = "Obtain Honor in Rated Arenas while in a Party.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80189] = { id = 80189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserving Teamwork", description = "The ability to strategize with others to take objectives is key to becoming a strong warrior. Go onto the battlefield, then return to me.", progress = "Finish off what you set to do then come back.", completion = "Great work! You have earned these.", objectives = "Obtain Honor in Rated Battleground Blitz or in Rated Battlegrounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80190] = { id = 80190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[80196] = { id = 80196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extract a Gem", description = "Any gem can be removed from your equipment using the Extract Gem ability.\n\nThe gem will not be destroyed.\n\nExtract a gem now.", objectives = "Extract the Chipped Deadly Sapphire from your equipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80197] = { id = 80197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combine Gems", description = "Prismatic gems can be combined to create a more powerful gem.\n\nCombine three Deadly Chipped Sapphires to create a Flawed Deadly Sapphire that grants additional Critical Strike when socketed.", completion = "As you find additional gems of the same type, you can continue to combine them to increase your combat capabilities.", objectives = "Use three Deadly Chipped Sapphires to combine them into a Flawed Deadly Sapphire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80202] = { id = 80202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hot Pollenate-o", description = "Important to make sure not take too much. Make sure hive healthy so can come back.\n\nBees eat pollen, yes? So fire bees eat fire pollen? Yes.\n\nBring fire pollen to bees. Grow strong. Bee productive.\n\nCheck edge of hive for flowers bees not get to yet. When catch fire, you got good one.", progress = "Just a little bit on fire. You tough, you be okay.", completion = "Good. Healthy hive make happy wax.", objectives = "Gather pollen from Pollen Rich Cinderblooms and return it to nearby bees before it goes out.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80203] = { id = 80203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Social Clues", description = "<The nerubian keeps her voice low, a careful eye on the guards behind you.>\n\nThe Weaver sent you, yes? I arrived to petition the Magistrate's approval for Ascension--to infiltrate high society, of course.\n\nBut he's missing. A rather large inconvenience.\n\nI need to ask around. You're just what I've been waiting for! You may pretend to be my... servant. Pet? Whatever makes it more palatable to you.\n\nI so rarely get to work alongside a friend. We will have fun together, fellow spy.", progress = "I have a few old friends who recently Ascended. Surely, one of them has heard something they would be willing to share. For old time's sake.\n\nAnd if not, maybe jealousy in seeing my fashionable new pet will inspire them to offer up what they know.", completion = "I knew Ascension changed people, but... They were my friends. And now, they don't even want to be seen with me.\n\nIt makes me wonder... if I succeed in all this, will I even still be myself?\n\n<Tx'itk shakes her head.>\n\nIt doesn't matter. I'll do what needs to be done.", objectives = "Help Orator Tx'itk ask around to find the Magistrate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80204] = { id = 80204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Espionage and Ventriloquism", description = "The Puppetmaster is our best lead for finding the Magistrate.\n\nBut is it just me, or did those puppets seem... horrifically lifelike? If this artist is behind the Magistrate's disappearance, he certainly isn't just off to see a puppet show.\n\nWe should investigate the Puppetmaster's workshop. Question him, or at least ransack his things. Just a bit. Until we find something useful.\n\nYou'll have to keep playing your rather undignified role in this charade. But it will pay off for us.", progress = "<Orator Tx'itk lowers her voice.>\n\nSomething isn't right here. Play along just a while longer. Let's see what else we can find.", completion = "The Magistrate is definitely in danger. We must act quickly before I lose my chance at Ascension.", objectives = "Investigate the Puppetmaster's Workshop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80205] = { id = 80205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pulling Strings", description = "Just think of it! Overcrawlers, war prisoners, civilians, fellow nerubians, important nobility being kidnapped and turned into puppets right under the Magistrate's nose.\n\nIt's horrific--and exactly what I needed! If we save the Magistrate from this fate, he'll owe me. Not just for saving his life, but to keep quiet about all this.\n\nWe're off to the theater, then. If you can keep the Puppetmaster occupied, I'll free High Elevator Etak'kaht from his grasp.\n\nHopefully he's not part of the show yet.", completion = "I'm thrilled. There couldn't have been a more perfect opportunity to get the Magistrate's attention. And the Weaver will be pleased to hear we have him in our pocket indefinitely, with this blackmail situation.\n\nNow, I suppose I'm off to the Transformatory.\n\n<Tx'itk shudders subtly.>\n\nI... I must not let my resolve falter now. The Weaver has asked this of me. I will be her eyes.", objectives = "Confront the Puppetmaster to rescue High Elevator Etak'kaht.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80206] = { id = 80206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marionette Mercy", description = "It's perfect! The Puppetmaster is so interested in adding you to his collection, he literally invited us to go rescue the Magistrate.\n\nI don't want to imply I've been using you as bait this entire time, but... Let's just say certain calculated risks have paid off.\n\nEven such a skilled artist must have a way to correct potential errors. There has to be an antitoxin of sorts for that paralytic around here somewhere!\n\nFind it. And perhaps we test it before we go use it on the Magistrate. Just in case.", progress = "I would worry we're taking too long, but considering how dramatic that Puppetmaster is, I can't imagine he'll start the show without us.\n\nWe should be prepared for something... rather unpleasant at that theater.", completion = "Just what we were looking for.\n\nAnd about using you as bait... You know it's not personal in our line of work, friend.\n\nI was open from the start of all this that you were the status symbol I needed to navigate this area and socially manipulate the Ascended.\n\nAnd if there's one thing I know to bet on, it's the ability of the Ascended to covet power flaunted over others.", objectives = "Find the Puppetmaster's Antiparalytic Serum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80207] = { id = 80207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How Scandalous!", description = "Did you see anything?\n\nI was just at the Forgegrounds picking up a jewelry commission and all of a sudden everyone was shouting like the Coreway was under attack--again.\n\nBut it was not that...\n\nSome peacekeepers were heading towards the depot--where crafting shipments are sent up from the Deeps. I bet it's something to do with the machine speakers!\n\nThe peacekeepers ushered everyone away before I could see what had happened. But maybe you can sneak a glimpse?", completion = "Move along. This is an ongoing--Oh, {name}, my apologies.\n\nWe may actually need your assistance.", objectives = "Investigate the disturbance near the Forgegrounds in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80208] = { id = 80208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Digging into Trouble" }
quests[80209] = { id = 80209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Oddball in Dornogal", description = "We have received reports that an eccentric Arathi is accosting our citizens. We have little experience with outsiders and my superiors are wary of a diplomatic incident.\n\nI have been tasked with finding this \"Lamplighter\" and resolving his concerns. You have worked with the Arathi before - can you assist me?\n\nI have a list of earthen who have reported the Lamplighter. You can interview half the list. Between us, we can hopefully locate the Arathi before he troubles more citizens.", completion = "This is not quite what I was expecting.\n\nHe is certainly odd but a troublemaker? I think not.", objectives = "Interview Concerned Dornogal Citizens to locate the Arathi Lamplighter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80210] = { id = 80210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Found Around the Unbound", description = "This Lamplighter is looking for his fellow Arathi. The foreman says he directed an Arathi shipwright to Freywold Village.\n\nMy superiors insist that Peacekeepers do not leave Dornogal... but per their orders, I must assist Kaerter. And to do that, I have no choice but to leave the city.\n\n<Leif quickly hides a smile.>\n\nIt is decided then. If you are willing, please meet us at Freywold Village. Your continued aid would be appreciated.", completion = "It seems the locals have taken issue with our foreign companion. I am attempting to defuse the situation as best I can.\n\nBut we have more pressing problems.", objectives = "Meet Peacekeeper Leif outside Freywold Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80211] = { id = 80211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pillage of Freywold Village", description = "The Arathi shipwright was here but has moved on with most of her entourage. She had left a few Arathi behind but...\n\nSoon after the shipwright left, earthen started disappearing. The villagers suspected the Arathi but had no proof. Then one day, the remaining Arathi left town in the middle of the night.\n\nThe locals said the Arathi stayed at the inn. Can you look there for any clues as to where the Arathi are now?\n\nGiven the villagers' hostility, the Lamplighter and I shall remain here for the moment.", progress = "I am attempting to convince the villagers that the Lamplighter is not involved in these disappearances.\n\nDid you find anything useful?", completion = "If I understand correctly, the Arathi are abducting earthen?\n\nAnd they are also killing each other?\n\nWhat madness is this?", objectives = "Search for clues as to where the Arathi went.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80212] = { id = 80212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Abductors' Obstructors", description = "The Order of Night is clearly interested in our resources. They have abducted earthen to harvest for them and may continue taking others. We must stop them.\n\nThe next largest earthen settlement is Rambleshire. If the Order needs more workers, they might have gone there to get them.\n\nGo on ahead {name}. I must first speak with Kaerter about why the Arathi are doing this.", completion = "While we have not yet seen any Arathi, there is an uneasiness about the town.\n\nKaerter believes the Order is here. He says they are simply waiting for a moment to strike.", objectives = "Meet Peacekeeper Leif at Rambleshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80213] = { id = 80213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holy Fire in Rambleshire", description = "I'm certain there are still Order folks sneaking around here. Now they might be carrying messages on them, just like the clues you found in Freywold. \n\nYou and I are gonna find out.\n\nHere, take these thuribles. They might look like tiny incense burners, but I've enchanted them with Sacred Flame. \n\nJust throw one down and you'll get a big bang with a bright flash! Should be enough to stun anyone sneaking around. \n\nJust don't throw one at me! Got it?", progress = "Alright, I'll admit it, the little Pebble is pretty useful. He knows more about the earthen and the surface than I ever will. \n\nAnyway, did you find anything?", completion = "\"New friends\" huh?\n\nGuess I'm not the only one...\n\n<Kaerter freezes when he realizes what he's just said and suddenly points a finger at you.>\n\nYou didn't hear me say nothing, got it?", objectives = "Use Flashfire Thuribles to reveal Order of Night forces in Rambleshire, eliminate them, and search them for clues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80214] = { id = 80214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Time to Kill at the Lumber Mill", description = "Alright, let me see if I get all of this. The shipwright brings an entourage up here to get lumber for airships. \n\nBut the shipwright is actually Order of Night, along with most of her group. So they murder the loyal Arathi, kidnap earthen, and force them to run the lumber mill up here.\n\nAnd now we gotta deal with the Order AND whoever their new friends are.\n\n<Kaerter swears and shakes his head.>\n\nC'mon, let's head to the mill. We got a lot of bad guys to kill and time's wastin'.", completion = "Nerubians. Lots and lots of nerubians.\n\nBy Beledar's Light do I hate nerubians.", objectives = "Meet Lamplighter Kaerter outside of Skolzgal Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80215] = { id = 80215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungirthin' the Earthen", description = "While I do enjoy beating the black blood out of nerubians, we must save the earthen prisoners first.\n\nI saw they're being held by Arathi ball and chain. Someone like you should be able to shatter them pretty quick. Just... do that thing you do!\n\nOh, and we should split up to cover more ground. Yeah Leif's gonna complain, but he's always complaining anyway.", completion = "Well done. I will lead the few I was able to rescue to safety.", objectives = "Free 8 Abducted Lumberjacks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80216] = { id = 80216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Concealed in the Weald", description = "The nerubians seem to be in league with the Arathi. Many of them are guarding the mill, but I am sure there are more than we can see.\n\nWe cannot allow such a large enemy force to operate unimpeded this close to Rambleshire.\n\nThe nerubians attacked and destroyed large sections of Dornogal not too long ago. The Order of Night Arathi are abducting and enslaving our people.\n\nWe must eliminate as many of them as we can. Preferably all of them.", progress = "The more enemies we eliminate, the safer we will all be.", completion = "That should disrupt their operation. Let us hope it is enough for now.", objectives = "Eliminate Shadowsilk forces at the Skolzgal Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80217] = { id = 80217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lamplight for the Shipwright", description = "Where is Kaerter now? Did he go off on his own again?\n\n<Leif sighs.>\n\nWe've rescued the earthen and eliminated many hostile forces, but our task is not yet complete.\n\nShortly before you arrived, we spotted a group of Arathi traveling up this hill. One of them was identified as the Arathi shipwright.\n\nThe shipwright is the leader here. Losing her will cripple their efforts to utilize the mill.\n\nHead up the hill and find her before she can escape.", completion = "Kaerter is injured. He will not be an effective fighter until he heals.", objectives = "Confront the Arathi shipwright.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80218] = { id = 80218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up to No Good Down in Silkwood", description = "The Order is moving the wood through the nerubians. Leif said he saw the shipwright leave the cave and head down to the beach. \n\nThe nerubian tunnel must be down there. You're going to have to seal that Flameforsaken passage.\n\nWhile slinking around, I noticed the Order brought explosive barrels with them. Find a few and use them to blow the tunnel.\n\nGet going {name}. I'll be right behind you.", progress = "Did you take out the tunnel?", completion = "Good stuff {name}. That should put a dent in their plans!\n\nWith that tunnel gone, ain't no way for them to send that wood to Hallowfall now. That makes the mill all but worthless.\n\nPhew! Order stopped, earthen saved, nerubians killed. Job well done if you ask me!\n\nI don't know 'bout you, but I could use a vacation.", objectives = "Collect Silkwood Explosive Barrels, then destroy the nerubian tunnel at Silkwood Grotto.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80219] = { id = 80219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dornogal Drift", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
