quests[80295] = { id = 80295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocks, Water and Elemental Fodder" }
quests[80310] = { id = 80310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting Sun Garrison", description = "Might you be willing to find Anji at the Setting Sun Garrison to the west? She's been tasked with preparing fresh-faced pandaren to aid the cause. You could show them a thing or two as well, I imagine.", completion = "You I can work with. Let's show these trainees a thing or two about how a real {class} fights.", objectives = "Speak to Anji Autumnlight at the Setting Sun Garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80311] = { id = 80311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Order of the Cloud Serpent", description = "Widing toortles is da best!\n\nBut widing cloud serpents is even better!\n\nThere's some peepos at da Arboweetum who wide cloud serpents and can teach you how!", completion = "Ah, another student of the skies. Welcome to the Arboretum.", objectives = "Speak to Elder Anli at The Arboretum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80312] = { id = 80312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gasping Plea", description = "<A gasping, pathetic-looking fish taken from the corpse of a kobyss flops weakly in your hand. Its beady eye twitches, and you suddenly hear a breathless voice in the recesses of your mind.>\n\nThe water. Take me to the water. Away from these kobyss wretches. Away from the sky.", completion = "<The fish gulps down saltwater to regain its breath and then turns to look at you with intelligent eyes.>\n\nI live, thanks to you. The shade of these rocks suits me nicely for the work to be done. \n\nAllow me to repay your selfless gesture.", objectives = "Put the strange fish in safe waters near the kobyss camp at Sunless Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80313] = { id = 80313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tidal Charms", description = "<When the fish speaks, its lips do not move. You hear its voice in your head.>\n\nNo doubt you have found that your senses cannot be trusted when dealing with the kobyss. A tremendous power, is it not? It is only fair that you show them the power they wield is not theirs alone.\n\nI will show you how to craft a tool to lure and destroy them. You will find their kind carry shards taken from the deep. Bring them to me.", progress = "Bring the materials. Only then can we continue.", completion = "Glinting abyssal shards and strands of coral. Bound with words of power and worn around the neck, I will show you how to trick the senses of your enemies.", objectives = "Collect 12 Sunless Shards from the kobyss at Sunless Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80314] = { id = 80314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voices from the Deep", description = "To deceive the senses of these kobyss is one matter. To know what will captivate them is another. They champ and drool at the thought of devouring your kind. But it is the voices of the deep that transfix them and lower their guard. It's then that you will strike.\n\nSearch their shrines to gain an insight for what these wretches hold sacred. See how they have twisted the bellowing truths that lie below.", progress = "What have you learned?", completion = "You see now what the kobyss revere. It is time to put that dark knowledge to use.", objectives = "Study three ritual sites for insights on the kobyss.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[80315] = { id = 80315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alluring Offer", description = "It is done. Take this tidal charm, cloak your form in the darkness of the sea, and unmake the kobyss. Their strongest warriors gather and scheme against your kind upon that central island. With the lure, they will not see you for what you are. Use that advantage to become their end.\n\nBut understand, as the kobyss fail to, this is a power you borrow. It belongs to the sea.", progress = "Isolate them. Destroy them.", completion = "With this, the lesson has been given. They will think twice before considering my kind as meat.\n\nYou kill well, land-walker. But the power of the deep must be returned. Our time together nears its end.", objectives = "Lure and assassinate Gillcarver and his Kobyss Tidemarshals on the island off the Sunless Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
